using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
static class EstimatePdf {
 static readonly Encoding Encoding1252=Encoding.GetEncoding(1252);
 static string Escape(string s){return s.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)");}
 public static string Heading(string report){return report.Contains("CONFIGURATION REVIEW")||report.Contains("SPLICE, DEVELOPMENT & HOOKS")?"SPLICE, DEVELOPMENT & HOOKS | CALCULATION SHEET":"BEAM ESTIMATE | BACKUP QUANTITIES & CALCULATIONS";}
 public static List<List<string>> Pages(string report){var pages=new List<List<string>>();var page=new List<string>();pages.Add(page);foreach(string raw in report.Replace("\r","").Split('\n')){if(raw=="\f"){if(page.Count>0){page=new List<string>();pages.Add(page);}continue;}string line=raw.Replace("\t","    ");do{int take=Math.Min(100,line.Length);if(line.Length>100){int split=line.LastIndexOf(' ',99,50);if(split>45)take=split;}if(page.Count>=54){page=new List<string>();pages.Add(page);}page.Add(line.Substring(0,take));line=line.Substring(take).TrimStart();}while(line.Length>0);}return pages;}
 static byte[] Stream(string dictionary,byte[] data){return Encoding1252.GetBytes("<< "+dictionary+" /Length "+data.Length+" >>\nstream\n").Concat(data).Concat(Encoding1252.GetBytes("\nendstream")).ToArray();}
 public static void Write(string path,string report){var project=ProjectInfoStore.Read();var security=new PdfSecurity();var pages=Pages(report);var objects=new List<byte[]>();Action<string> add=s=>objects.Add(Encoding1252.GetBytes(s));add("<< /Type /Catalog /Pages 2 0 R >>");add("<< /Type /Pages /Count "+pages.Count+" /Kids ["+string.Join(" ",Enumerable.Range(0,pages.Count).Select(i=>(5+i*2)+" 0 R"))+"] >>");int fontFileId=5+2*pages.Count,fontDescriptorId=fontFileId+1;add("<< /Type /Font /Subtype /TrueType /BaseFont /"+ReportFont.PostScriptName+" /FirstChar 0 /LastChar 255 /Widths ["+ReportFont.Widths+"] /FontDescriptor "+fontDescriptorId+" 0 R /Encoding /WinAnsiEncoding >>");objects.Add(Stream("/Type /XObject /Subtype /Image /Width 1200 /Height 1200 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode",security.Encrypt(PdfBrand.Jpeg,4)));
 for(int i=0;i<pages.Count;i++){int content=6+i*2;add("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 3 0 R >> /XObject << /WM 4 0 R >> >> /Contents "+content+" 0 R >>");var stream=new StringBuilder(PdfBrand.PdfCommands());stream.Append("q 0.55 G 0.5 w 72 722 m 559.28 722 l S Q BT /F1 10 Tf 85 Tz 0.12 0.18 0.25 rg 1 0 0 1 74 805 Tm ("+Escape(Heading(report))+") Tj ET BT /F1 8 Tf 85 Tz 0.35 0.42 0.5 rg 1 0 0 1 74 786 Tm (DTCE Tool Kit v"+Engine.Version+" | SI units | Print-only review copy) Tj ET BT /F1 8 Tf 85 Tz 0.12 0.18 0.25 rg 1 0 0 1 74 769 Tm ("+Escape(project.NameLine)+") Tj 1 0 0 1 74 755 Tm ("+Escape(project.LocationLine)+") Tj ET ");int y=707;foreach(string line in pages[i]){bool section=line.StartsWith("## ");if(section)stream.Append("q 0.90 0.94 0.98 rg 72 "+(y-3)+" 487.28 13 re f 0.13 0.34 0.57 rg 72 "+(y-3)+" 2 13 re f Q ");stream.Append("BT /F1 10 Tf 85 Tz 0.12 0.18 0.25 rg 1 0 0 1 74 "+y+" Tm ("+Escape(section?line.Substring(3):line)+") Tj ET ");y-=12;}stream.Append("q 0.77 0.82 0.88 RG 0.5 w 72 35 m 559.28 35 l S Q BT /F1 8 Tf 85 Tz 0.35 0.42 0.5 rg 1 0 0 1 74 21 Tm (Generated "+DateTime.Now.ToString("yyyy-MM-dd")+" | Lengths in mm unless noted) Tj 1 0 0 1 "+(559.28-("Page "+(i+1)+" / "+pages.Count).Length*ReportFont.Width/1000*8*.85).ToString("0.###",CultureInfo.InvariantCulture)+" 21 Tm (Page "+(i+1)+" / "+pages.Count+") Tj ET ");objects.Add(Stream("",security.Encrypt(Encoding1252.GetBytes(stream.ToString()),content)));}
 objects.Add(Stream("/Length1 "+ReportFont.Bytes.Length,security.Encrypt(ReportFont.Bytes,fontFileId)));add(ReportFont.Descriptor(fontFileId));int encryptId=objects.Count+1;add(security.Dictionary());string full=Path.GetFullPath(path),temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write)){Action<string> put=s=>{byte[] bytes=Encoding1252.GetBytes(s);f.Write(bytes,0,bytes.Length);};put("%PDF-1.6\n");var offsets=new List<long>{0};for(int i=0;i<objects.Count;i++){offsets.Add(f.Position);put((i+1)+" 0 obj\n");f.Write(objects[i],0,objects[i].Length);put("\nendobj\n");}long xref=f.Position;put("xref\n0 "+offsets.Count+"\n0000000000 65535 f \n");foreach(long offset in offsets.Skip(1))put(offset.ToString("D10",CultureInfo.InvariantCulture)+" 00000 n \n");put("trailer\n<< /Size "+offsets.Count+" /Root 1 0 R /Encrypt "+encryptId+" 0 R /ID [<"+PdfSecurity.Hex(security.Id)+"><"+PdfSecurity.Hex(security.Id)+">] >>\nstartxref\n"+xref+"\n%%EOF\n");}File.Copy(temp,full,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
